'use strict';

const path = require('path');
const fs = require('fs');

/**
 * SQLite Storage Adapter for express-gamekit.
 * Uses `better-sqlite3` loaded lazily.
 * 
 * Why better-sqlite3?
 * - Synchronous, zero-overhead execution loop in Node.js.
 * - Extremely fast compared to asynchronous sqlite3 wrapper.
 * - Simple single file database without external server setup.
 * - Zero background network dependencies.
 * 
 * @param {object} [options={}]
 * @param {string} [options.filename=':memory:'] - Database file path or ':memory:'
 * @returns {object} Storage adapter conforming to get, set, delete, list interface
 */
function sqliteStore(options = {}) {
  let Database;
  try {
    Database = require('better-sqlite3');
  } catch (err) {
    throw new Error(
      'To use sqliteStore, please install better-sqlite3: "npm install better-sqlite3"\n' +
      `Underlying error: ${err.message}`
    );
  }

  const filename = options.filename || ':memory:';
  if (filename !== ':memory:') {
    const dir = path.dirname(path.resolve(filename));
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
  }

  const db = new Database(filename);

  // Enable WAL mode for high performance concurrency if on disk
  if (filename !== ':memory:') {
    db.pragma('journal_mode = WAL');
  }

  // Ensure table exists
  db.exec(`
    CREATE TABLE IF NOT EXISTS gamekit_store (
      collection TEXT NOT NULL,
      id TEXT NOT NULL,
      data TEXT NOT NULL,
      PRIMARY KEY (collection, id)
    );
    CREATE INDEX IF NOT EXISTS idx_collection ON gamekit_store (collection);
  `);

  const selectStmt = db.prepare('SELECT data FROM gamekit_store WHERE collection = ? AND id = ?');
  const insertStmt = db.prepare(`
    INSERT INTO gamekit_store (collection, id, data)
    VALUES (?, ?, ?)
    ON CONFLICT(collection, id) DO UPDATE SET data = excluded.data
  `);
  const deleteStmt = db.prepare('DELETE FROM gamekit_store WHERE collection = ? AND id = ?');
  const listStmt = db.prepare('SELECT data FROM gamekit_store WHERE collection = ?');

  return {
    /**
     * Get a document by ID.
     */
    async get(collection, id) {
      const row = selectStmt.get(String(collection), String(id));
      if (!row) return null;
      try {
        return JSON.parse(row.data);
      } catch {
        return null;
      }
    },

    /**
     * Store or replace a document.
     */
    async set(collection, id, doc) {
      const json = JSON.stringify(doc);
      insertStmt.run(String(collection), String(id), json);
      return JSON.parse(json);
    },

    /**
     * Delete a document by ID.
     */
    async delete(collection, id) {
      const result = deleteStmt.run(String(collection), String(id));
      return result.changes > 0;
    },

    /**
     * List all documents in a collection.
     */
    async list(collection) {
      const rows = listStmt.all(String(collection));
      return rows.map(r => JSON.parse(r.data));
    },

    /**
     * Close underlying database connection.
     */
    close() {
      db.close();
    }
  };
}

module.exports = {
  sqliteStore
};
